// Full original ten-entry GPU pipeline; corrected/serialized input conventions.
#define INT
#include "native_kernels.cuh"
#include <fstream>
#include <vector>
#include <string>
#include <cassert>
#include <cstdint>
#include <algorithm>
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}
template<class T>std::vector<T> read(const char*path){std::ifstream f(path,std::ios::binary|std::ios::ate);assert(f);auto n=f.tellg();assert(n>=0&&n%sizeof(T)==0);std::vector<T>x(size_t(n)/sizeof(T));f.seekg(0);f.read((char*)x.data(),n);assert(f);return x;}
template<class T>struct Guarded{size_t n;T*base;std::vector<T>initial;Guarded(std::vector<T>payload):n(payload.size()),initial(n+64,T(0xa5a5a5a5)){std::copy(payload.begin(),payload.end(),initial.begin()+32);ck(cudaMalloc(&base,initial.size()*sizeof(T)));reset();}T*ptr(){return base+32;}void reset(){ck(cudaMemcpy(base,initial.data(),initial.size()*sizeof(T),cudaMemcpyHostToDevice));}std::vector<T>take(){std::vector<T>x(initial.size());ck(cudaMemcpy(x.data(),base,x.size()*sizeof(T),cudaMemcpyDeviceToHost));return x;}void guards(const std::vector<T>&x){for(size_t i=0;i<x.size();i++)if(i<32||i>=n+32)assert(x[i]==initial[i]);}void append(std::vector<double>&out){auto x=take();guards(x);out.insert(out.end(),x.begin(),x.end());}void readonly(){assert(take()==initial);}~Guarded(){cudaFree(base);}};
struct Case{int n;Guarded<int32_t>seq,v,w,wm,wca,w5,w3;Case(std::vector<int32_t>s):n(s.size()),seq(s),v(std::vector<int32_t>(n*n,INF)),w(std::vector<int32_t>(n*n,INF)),wm(std::vector<int32_t>(n*n,INF)),wca(std::vector<int32_t>(n*n,INF)),w5(std::vector<int32_t>(n+1,-777777)),w3(std::vector<int32_t>(n+1,-777777)){}void reset(){v.reset();w.reset();wm.reset();wca.reset();w5.reset();w3.reset();}void prefix(std::vector<double>&out){seq.append(out);for(auto*g:{&v,&w,&wm,&wca,&w5,&w3})g->append(out);}void init(){init_w5_and_w3<<<n+1,1>>>(n+1,w5.ptr(),w3.ptr());}void step(int d,fparam_t p){auto s=(fbase_t*)seq.ptr();auto vv=v.ptr();auto ww=w.ptr();auto mm=wm.ptr();auto pre=w5.ptr()+1;auto suf=w3.ptr();auto ca=wca.ptr();calc_V_hairpin_and_V_stack<<<n,1>>>(d,n,s,vv,p);calc_V_bulge_internal<<<n,dim3(16,16,1)>>>(d,n,s,vv,p);calc_V_exterior<<<n,1>>>(d,n,s,vv,pre,suf,p);calc_V_multibranch<<<n,1>>>(d,n,s,vv,mm,p);calc_coaxial<<<n,256>>>(d,n,s,vv,ww,pre,suf,p);calc_W<<<n,1>>>(d,n,s,vv,ww,p);calc_WM<<<n,256>>>(d,n,s,ww,mm,p);calc_wl_coax<<<n,256>>>(d,n,s,vv,ww,mm,p,ca);calc_w5_and_w3<<<1,256>>>(d,n,s,vv,pre,suf,p,ca);}
 void check(const std::vector<int32_t>&gold,size_t&offset,std::vector<double>&out,size_t&checked){for(auto*g:{&v,&w,&wm,&wca,&w5,&w3}){auto a=g->take();g->guards(a);for(size_t i=0;i<a.size();i++){out.push_back(a[i]);if(i>=32&&i<g->n+32){assert(offset<gold.size());if(a[i]!=gold[offset]){fprintf(stderr,"FRNA_SOURCE_CPU_MISMATCH gold_offset%zu local_guarded_index%zu actual%d expected%d\n",offset,i,a[i],gold[offset]);FILE*diag=fopen("diagnostic_gpu_array_Int32.bin","wb");assert(diag);fwrite(a.data(),4,a.size(),diag);fclose(diag);exit(3);}offset++;checked++;}}}seq.readonly();}
 void physical_final(std::vector<int32_t>&MFE){auto a=w5.take(),b=w3.take();assert(a[32]==0&&b[32+n]==0);assert(a[32+n]==b[32]&&b[32]<=0);MFE.push_back(b[32]);}
};
int main(){static_assert(sizeof(int_t)==4&&sizeof(fbase_t)==4);auto p=read<uint32_t>("params.bin");assert(p.size()*4==sizeof(fparam));Guarded<uint32_t>par(p);auto s=read<int32_t>("sequences.bin");assert(!s.empty()&&s[0]==6);size_t k=1;std::vector<Case*>cases;for(int c=0;c<s[0];c++){int n=s.at(k++);assert(n>4&&n<=77&&k+n<=s.size());std::vector<int32_t>seq(s.begin()+k,s.begin()+k+n);k+=n;for(int b:seq)assert(0<=b&&b<4);cases.push_back(new Case(seq));}assert(k==s.size());auto gold=read<int32_t>("serial_source_crosscheck.bin");assert(gold.size()==2205408);for(auto*c:cases){c->reset();c->init();for(int d=0;d<c->n-1;d++)c->step(d,(fparam_t)par.ptr());}ck(cudaDeviceSynchronize());
 for(int trial=1;trial<=5;trial++){std::vector<double>prefix,out,times;std::vector<int32_t>MFE;size_t offset=0,checked=0;par.append(prefix);for(auto*c:cases){c->reset();c->prefix(prefix);}if(trial==1){std::ofstream echo("diagnostic_actual_inputs_Float64.bin",std::ios::binary);echo.write((char*)prefix.data(),prefix.size()*8);assert(echo);}for(auto*c:cases){auto measure=[&](auto work){ck(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();work();ck(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count());};measure([&]{c->init();});c->check(gold,offset,out,checked);for(int d=0;d<c->n-1;d++){measure([&]{c->step(d,(fparam_t)par.ptr());});c->check(gold,offset,out,checked);}c->physical_final(MFE);}par.readonly();assert(offset==gold.size());assert(MFE==std::vector<int32_t>({-2760,0,-120,-40,0,-50}));size_t input_count=prefix.size();prefix.insert(prefix.end(),out.begin(),out.end());std::string name="output_trial"+std::to_string(trial)+".bin";std::ofstream f(name,std::ios::binary);f.write((char*)prefix.data(),prefix.size()*8);f.close();assert(f);double total=0;for(double t:times)total+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":0.0,\"max_rel_error\":null,\"metric_scope\":\"ExactInt32fullsourceCPUstatecrosscheck; independentglobalMFEcertificateforfivecontrols, notfull77basebiologicaloptimum\",\"timing_region\":\"sum_initialization_and_perdistance_fullninekernel_contextcompleted_segments_excludes_captures\",\"jit_excluded\":true,\"internal_repeats\":1,\"input_prefix_count\":%zu,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"},\"MFE_scaled_Int32\":[",trial,total,checked,input_count,name.c_str(),prefix.size());for(size_t i=0;i<MFE.size();i++)printf("%s%d",i?",":"",MFE[i]);printf("],\"segment_seconds\":[");for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("]}\n");fflush(stdout);}
 for(auto*c:cases)delete c;}
